"""MNIST canvas inference. Predictions require trained weights generated by scripts/train.py."""
from __future__ import annotations
import io, os, time
from datetime import datetime, timezone
from pathlib import Path
import numpy as np
from dotenv import load_dotenv
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.middleware.cors import CORSMiddleware
from PIL import Image, ImageOps
from pydantic import BaseModel, Field
from sqlalchemy import DateTime, Float, Integer, LargeBinary, String, create_engine, select
from sqlalchemy.orm import DeclarativeBase, Mapped, Session, mapped_column, sessionmaker
import torch
from torch import nn
load_dotenv()
ROOT=Path(__file__).resolve().parents[1];MODELS=ROOT/'models';DB=os.getenv('DATABASE_URL',f"sqlite:///{ROOT/'database'/'digits.db'}");(ROOT/'database').mkdir(exist_ok=True);DEVICE='cuda' if torch.cuda.is_available() else 'cpu';engine=create_engine(DB,connect_args={'check_same_thread':False} if DB.startswith('sqlite') else {});Sessions=sessionmaker(bind=engine)
class Base(DeclarativeBase):pass
class Saved(Base):
 __tablename__='predictions';id:Mapped[int]=mapped_column(primary_key=True);drawing:Mapped[bytes]=mapped_column(LargeBinary);digit:Mapped[int]=mapped_column(Integer);confidence:Mapped[float]=mapped_column(Float);model:Mapped[str]=mapped_column(String(20));inference_ms:Mapped[float]=mapped_column(Float);created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=lambda:datetime.now(timezone.utc))
class Metric(Base):
 __tablename__='models';name:Mapped[str]=mapped_column(String(20),primary_key=True);accuracy:Mapped[float]=mapped_column(Float);precision:Mapped[float]=mapped_column(Float);recall:Mapped[float]=mapped_column(Float);f1:Mapped[float]=mapped_column(Float);parameters:Mapped[int]=mapped_column(Integer)
class MLP(nn.Module):
 def __init__(self):super().__init__();self.net=nn.Sequential(nn.Flatten(),nn.Linear(784,256),nn.ReLU(),nn.Dropout(.3),nn.Linear(256,128),nn.ReLU(),nn.Dropout(.3),nn.Linear(128,10))
 def forward(self,x):return self.net(x)
class CNN(nn.Module):
 def __init__(self):super().__init__();self.features=nn.Sequential(nn.Conv2d(1,32,3,padding=1),nn.ReLU(),nn.MaxPool2d(2),nn.Conv2d(32,64,3,padding=1),nn.ReLU(),nn.MaxPool2d(2));self.head=nn.Sequential(nn.Flatten(),nn.Linear(64*7*7,128),nn.ReLU(),nn.Dropout(.3),nn.Linear(128,10))
 def forward(self,x):return self.head(self.features(x))
def session():
 s=Sessions()
 try:yield s
 finally:s.close()
def net(name):
 model=MLP() if name=='mlp' else CNN();path=MODELS/f'{name}.pt'
 if not path.exists():raise HTTPException(503,f"{name.upper()} weights are missing. Run scripts/train.py or install the versioned model asset.")
 model.load_state_dict(torch.load(path,map_location=DEVICE,weights_only=True));return model.to(DEVICE).eval()
def tensor(raw):
 try:im=Image.open(io.BytesIO(raw)).convert('L');im=ImageOps.invert(im);box=im.getbbox();im=im.crop(box) if box else im;im.thumbnail((20,20));canvas=Image.new('L',(28,28));canvas.paste(im,((28-im.width)//2,(28-im.height)//2));a=np.asarray(canvas,dtype=np.float32)/255.;return torch.from_numpy(a).unsqueeze(0).unsqueeze(0),canvas
 except Exception as e:raise HTTPException(400,f'Invalid drawing: {e}')
def run(name,raw,save=True):
 x,_=tensor(raw);m=net(name);start=time.perf_counter()
 with torch.no_grad():p=torch.softmax(m(x.to(DEVICE)),1)[0].cpu().numpy()
 elapsed=(time.perf_counter()-start)*1000;digit=int(np.argmax(p));result={'model':name,'predicted_digit':digit,'confidence':float(p[digit]),'probabilities':p.tolist(),'inference_ms':round(elapsed,3)}
 if save:
  with Sessions() as s:s.add(Saved(drawing=raw,digit=digit,confidence=float(p[digit]),model=name,inference_ms=elapsed));s.commit()
 return result
app=FastAPI(title='Draw-a-Digit Neural Network',version='2.0.0');app.add_middleware(CORSMiddleware,allow_origins=os.getenv('CORS_ORIGINS','http://localhost:3002,http://127.0.0.1:3002').split(','),allow_credentials=True,allow_methods=['*'],allow_headers=['*'])
@app.on_event('startup')
def init():Base.metadata.create_all(engine)
@app.get('/health')
def health():return {'status':'healthy','device':DEVICE,'models':[x.stem for x in MODELS.glob('*.pt')]}
@app.post('/predict')
async def predict(file:UploadFile=File(...),model:str='cnn'):
 if model not in ('mlp','cnn'):raise HTTPException(422,'model must be mlp or cnn')
 return run(model,await file.read())
@app.post('/predict/compare')
async def compare(file:UploadFile=File(...)):
 raw=await file.read();results=[run('mlp',raw,False),run('cnn',raw,False)];return {'results':results,'more_confident':max(results,key=lambda x:x['confidence'])['model'],'faster':min(results,key=lambda x:x['inference_ms'])['model']}
@app.get('/drawings')
def drawings():
 with Sessions()as s:return [{'id':x.id,'predicted_digit':x.digit,'confidence':x.confidence,'model':x.model,'inference_ms':x.inference_ms,'timestamp':x.created_at.isoformat()}for x in s.scalars(select(Saved).order_by(Saved.created_at.desc()).limit(50)).all()]
@app.get('/models')
def models():
 with Sessions()as s:return [{'name':x.name,'accuracy':x.accuracy,'parameters':x.parameters}for x in s.scalars(select(Metric)).all()]
@app.get('/metrics')
def metrics():
 with Sessions()as s:return [{'model':x.name,'accuracy':x.accuracy,'precision':x.precision,'recall':x.recall,'f1_score':x.f1,'parameters':x.parameters}for x in s.scalars(select(Metric)).all()]
